Mesh<Point, double> result;
std::unordered_set<RT::Cell_handle, typename RT::Cell_hash_function> visited_cells;
for (auto it = rt.finite_edges_begin(); it != rt.finite_edges_end(); ++it) {
    RT::Edge e = *it;
    if (is_small_edge(rt, e, threshold)) continue;
    RT::Cell_handle c1 = e.first;
    RT::Cell_handle c2 = rt.other_cell(e.first, e.second, e.third);
    if (c1 == nullptr || c2 == nullptr) continue;
    std::vector<Point> face_points;
    std::array<RT::Vertex_handle, 3> vertices;
    int k = e.second;
    int i = e.third;
    int j = 3 - k - i;
    vertices[0] = c1->vertex(i);
    vertices[1] = c1->vertex(j);
    vertices[2] = c1->vertex(k);
    for (int idx = 0; idx < 3; ++idx) {
        RT::Vertex_handle v = vertices[idx];
        if (rt.is_infinite(v)) continue;
        face_points.push_back(v->point().point());
    }
    if (face_points.size() < 3) continue;
    double edge_length = std::sqrt(rt.segment(e).squared_length());
    result.faces.push_back(face_points);
    result.edge_lengths.push_back(edge_length);
}
return result;

